import type {Point,WorldMapDefinition} from './schema';
import {canStand,canWalk} from './geometry';
const components=new WeakMap<WorldMapDefinition,Point[]>();
const key=(p:Point)=>`${p.x},${p.y}`;
function exits(map:WorldMapDefinition):Point[]{
 const seeds:Point[]=[];
 for(const {rect:r} of map.exits){
  const center={x:r.x+r.width/2,y:r.y+r.height/2};if(canStand(map,center))seeds.push(center);
  for(let x=Math.ceil(r.x*2)/2;x<=r.x+r.width;x+=.5)for(let y=Math.ceil(r.y*2)/2;y<=r.y+r.height;y+=.5)if(canStand(map,{x,y}))seeds.push({x,y});
 }
 // Isolated authored test/interior maps without exits retain their spawn component.
 if(!map.exits.length&&canStand(map,map.defaultSpawn))seeds.push(map.defaultSpawn);
 return seeds;
}
export function exitComponent(map:WorldMapDefinition):readonly Point[]{
 const known=components.get(map);if(known)return known;
 const seeds=exits(map),queue:Point[]=[],seen=new Set<string>();
 const add=(p:Point)=>{const id=key(p);if(!seen.has(id)){seen.add(id);queue.push(p);}};
 for(const p of seeds)for(let x=Math.floor(p.x*2)/2-.5;x<=Math.ceil(p.x*2)/2+.5;x+=.5)for(let y=Math.floor(p.y*2)/2-.5;y<=Math.ceil(p.y*2)/2+.5;y+=.5)if(canWalk(map,p,{x,y}))add({x,y});
 for(let i=0;i<queue.length;i++){
  const p=queue[i];
  for(const [dx,dy] of [[.5,0],[-.5,0],[0,.5],[0,-.5]]){
   const n={x:p.x+dx,y:p.y+dy};if(!seen.has(key(n))&&canWalk(map,p,n))add(n);
  }
 }
 const result=[...seeds,...queue];components.set(map,result);return result;
}
export function isExitConnected(map:WorldMapDefinition,p:Point):boolean {
 if(!canStand(map,p))return false;
 if(exits(map).some(exit=>canWalk(map,p,exit)))return true;
 return exitComponent(map).some(n=>Math.abs(n.x-p.x)<=1&&Math.abs(n.y-p.y)<=1&&canWalk(map,p,n));
}
export function safeExitPosition(map:WorldMapDefinition,p:Point):Point|null {
 if(isExitConnected(map,p))return p;
 const points=[...exitComponent(map)].sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y)||a.y-b.y||a.x-b.x);
 // An edited/corrupt map can cover every exit. Callers must reject the edit
 // or restore to the static safe world; never throw or keep disconnected feet.
 if(!points.length)return null;
 return points[0];
}

import type { Point, Rect, WorldMapDefinition } from "./schema";

export const PLAYER_RADIUS = .22;
export function contains(rect: Rect, p: Point): boolean {
  return p.x >= rect.x && p.y >= rect.y && p.x <= rect.x + rect.width && p.y <= rect.y + rect.height;
}
export function canStand(map: WorldMapDefinition, p: Point, radius = PLAYER_RADIUS): boolean {
  if (!Number.isFinite(p.x) || !Number.isFinite(p.y) || p.x < radius || p.y < radius || p.x > map.bounds.width-radius || p.y > map.bounds.height-radius) return false;
  if(!map.walkable.some(rect=>contains(rect,p)))return false;
  const left=p.x-radius,right=p.x+radius,top=p.y-radius,bottom=p.y+radius;
  const cuts=[left,right,...map.walkable.flatMap(r=>[r.x,r.x+r.width]).filter(x=>x>left&&x<right)].sort((a,b)=>a-b);
  for(let i=1;i<cuts.length;i++) {
    if(cuts[i]===cuts[i-1])continue;
    const x=(cuts[i]+cuts[i-1])/2;
    const spans=map.walkable.filter(r=>x>=r.x&&x<=r.x+r.width).map(r=>[r.y,r.y+r.height]).sort((a,b)=>a[0]-b[0]);
    let covered=top;
    for(const [start,end] of spans){if(start>covered)break;if(end>covered)covered=end;if(covered>=bottom)break;}
    if(covered<bottom)return false;
  }
  return map.colliders.every(({rect}) => {
    const x = Math.max(rect.x, Math.min(p.x, rect.x+rect.width));
    const y = Math.max(rect.y, Math.min(p.y, rect.y+rect.height));
    return Math.hypot(p.x-x,p.y-y) > radius;
  });
}
export function canWalk(map: WorldMapDefinition, from: Point, to: Point, radius=PLAYER_RADIUS): boolean {
  if(!canStand(map,from,radius)||!canStand(map,to,radius))return false;
  const steps = Math.max(1, Math.ceil(Math.hypot(to.x-from.x,to.y-from.y)/.1));
  for(let i=0;i<=steps;i++) if(!canStand(map,{x:from.x+(to.x-from.x)*i/steps,y:from.y+(to.y-from.y)*i/steps},radius)) return false;
  return true;
}
export function movePlayer(map: WorldMapDefinition, from: Point, delta: Point): Point {
  const length=Math.hypot(delta.x,delta.y), steps=Math.max(1,Math.ceil(length/.1));
  let p=from;
  for(let i=0;i<steps;i++) {
    const next={x:p.x+delta.x/steps,y:p.y+delta.y/steps};
    if(canWalk(map,p,next)) p=next;
    else {
      const x={x:next.x,y:p.y},y={x:p.x,y:next.y};
      if(canWalk(map,p,x)) p=x;
      else if(canWalk(map,p,y)) p=y;
    }
  }
  return p;
}
export function findPath(map: WorldMapDefinition, from: Point, to: Point, radius=PLAYER_RADIUS): Point[] {
  if(!canStand(map,from,radius)||!canStand(map,to,radius)) return [];
  if(canWalk(map,from,to,radius)) return [to];
  const key=(p:Point)=>`${p.x},${p.y}`;
  const connect=(p:Point)=>{
    const found:Point[]=[];
    for(let x=Math.floor(p.x*2)/2-.5;x<=Math.ceil(p.x*2)/2+.5;x+=.5)
      for(let y=Math.floor(p.y*2)/2-.5;y<=Math.ceil(p.y*2)/2+.5;y+=.5)
        if(canWalk(map,p,{x,y},radius)) found.push({x,y});
    return found;
  };
  const starts=connect(from),ends=new Set(connect(to).map(key));
  const parents=new Map<string,Point|null>(starts.map(p=>[key(p),null]));
  const costs=new Map<string,number>();
  type Node={p:Point;cost:number;score:number};
  const heap:Node[]=[];
  const push=(node:Node)=>{let i=heap.length;heap.push(node);while(i>0){const parent=(i-1)>>1;if(heap[parent].score<=node.score)break;heap[i]=heap[parent];i=parent;}heap[i]=node;};
  const pop=()=>{const root=heap[0],last=heap.pop()!;if(heap.length){let i=0;while(i*2+1<heap.length){let child=i*2+1;if(child+1<heap.length&&heap[child+1].score<heap[child].score)child++;if(heap[child].score>=last.score)break;heap[i]=heap[child];i=child;}heap[i]=last;}return root;};
  for(const p of starts){const cost=Math.hypot(p.x-from.x,p.y-from.y);costs.set(key(p),cost);push({p,cost,score:cost+Math.hypot(p.x-to.x,p.y-to.y)});}
  for(let expanded=0;heap.length&&expanded<100000;expanded++) {
    const node=pop(),p=node.p;
    if(node.cost!==costs.get(key(p)))continue;
    if(ends.has(key(p))) {
      const path:Point[]=[to]; let current:Point|null=p;
      while(current) {path.unshift(current);current=parents.get(key(current))??null;}
      const smooth:Point[]=[];let previous=from;
      for(let n=0;n<path.length;n++) if(n===path.length-1 || !canWalk(map,previous,path[n+1],radius)) {smooth.push(path[n]);previous=path[n];}
      return smooth;
    }
    for(const [dx,dy] of [[.5,0],[-.5,0],[0,.5],[0,-.5]]) {
      const n={x:p.x+dx,y:p.y+dy},id=key(n),cost=node.cost+.5;
      if(cost>=(costs.get(id)??Infinity)||!cachedEdge(map,p,n,radius))continue;
      parents.set(id,p);costs.set(id,cost);push({p:n,cost,score:cost+Math.hypot(n.x-to.x,n.y-to.y)});
    }
  }
  return [];
}
export function nearbyAnchors(map:WorldMapDefinition,p:Point) {
  return map.anchors.filter(a=>Math.hypot(a.position.x-p.x,a.position.y-p.y)<=a.radius).sort((a,b)=>Math.hypot(a.position.x-p.x,a.position.y-p.y)-Math.hypot(b.position.x-p.x,b.position.y-p.y));
}

const edges=new WeakMap<WorldMapDefinition,Map<string,boolean>>();
function cachedEdge(map:WorldMapDefinition,a:Point,b:Point,radius:number) {
 let cache=edges.get(map);if(!cache){cache=new Map();edges.set(map,cache);}
 const ak=`${a.x},${a.y}`,bk=`${b.x},${b.y}`,key=ak<bk?`${radius}:${ak}:${bk}`:`${radius}:${bk}:${ak}`;
 const known=cache.get(key);if(known!==undefined)return known;
 const result=canWalk(map,a,b,radius);cache.set(key,result);return result;
}

import { z } from "zod";

const finite = z.number().finite();
export const pointSchema = z.object({ x: finite, y: finite });
export const facingSchema = z.enum(["north", "east", "south", "west"]);
export const rectSchema = pointSchema.extend({ width: finite.positive(), height: finite.positive() });
const spawnSchema = pointSchema.extend({ facing: facingSchema });
export const featureSchema = z.enum(["restaurant", "apartment", "cats", "repairs", "garden", "exploration"]);
export const worldMapSchema = z.object({
  version: z.literal(1), id: z.string().min(1),
  bounds: z.object({ width: finite.positive().max(1024), height: finite.positive().max(1024) }),
  defaultSpawn: spawnSchema,
  walkable: z.array(rectSchema).min(1),
  colliders: z.array(z.object({ id: z.string(), rect: rectSchema })),
  occluders: z.array(z.object({ id: z.string(), rect: rectSchema, height: finite.nonnegative(), fadeWhenPlayerBehind: z.boolean() })),
  entrances: z.array(z.object({ id: z.string(), position: pointSchema, facing: facingSchema })),
  exits: z.array(z.object({ id: z.string(), rect: rectSchema, targetMapId: z.string(), targetEntranceId: z.string(), kind: z.enum(["door", "stairs", "path"]) })),
  anchors: z.array(z.object({ id: z.string(), position: pointSchema, radius: finite.positive(), featureId: featureSchema, interactionId: z.string() })),
  terrain: z.array(z.object({ id: z.string(), rect: rectSchema, material: z.string(), variant: z.union([z.string(), z.number()]) })),
  props: z.array(z.object({ id: z.string(), kind: z.string(), position: pointSchema, width: finite.positive(), height: finite.positive(), layer: z.enum(["ground", "object", "foreground"]), variant: z.union([z.string(), z.number()]) })),
  palette: z.record(z.string(), z.tuple([z.number().min(0).max(255), z.number().min(0).max(255), z.number().min(0).max(255)])),
  npcHooks: z.array(z.object({ id: z.string(), position: pointSchema, route: z.array(pointSchema), characterId: z.string() })),
  landmarks: z.array(z.object({ id: z.string(), position: pointSchema, kind: z.string() })),
});
export type WorldMapDefinition = z.infer<typeof worldMapSchema>;
export type Point = z.infer<typeof pointSchema>;
export type Rect = z.infer<typeof rectSchema>;
export type Facing = z.infer<typeof facingSchema>;
export type FeatureId = z.infer<typeof featureSchema>;
export type Spawn = Point & { facing: Facing };
export type WorldState = {
  version: 1; mapId: string; position: Point; facing: Facing;
  returnPositions: Record<string, Spawn>;
  activeActivity: Exclude<FeatureId, "exploration"> | null;
  activeAnchorId: string | null;
  life?: import("./life").LifeState;
};

import { z } from 'zod';
import { lineFor } from '../../features/cats/content';
import type { Line, Position } from '../../contracts';
import type { ActorPose, Affordance, LifeContext, LifeEvent, LifePlan, Navigation } from './model';

const id = z.string().min(1).max(200);
const discovery = z.strictObject({ mapId: id, landmarkId: id, day: z.number().int().positive().max(Number.MAX_SAFE_INTEGER) });
const reaction = z.strictObject({ mapId: id, targetId: id, reaction: z.enum(['wave', 'sit', 'watch', 'flutter', 'ripple', 'sway']), atMs: z.number().finite().nonnegative() });
export const lifeStateSchema = z.strictObject({
  version: z.literal(1),
  elapsedMs: z.number().finite().nonnegative().default(0),
  discoveries: z.array(discovery).max(10000),
  reactions: z.array(reaction).max(100),
  serviceDepartures: z.array(z.strictObject({ day: z.number().int().positive().max(Number.MAX_SAFE_INTEGER), table: z.number().int().min(1).max(4), orderId: id })).max(4).default([]),
  pauses: z.array(z.strictObject({ mapId: id, targetId: id, startMs: z.number().finite().nonnegative(), durationMs: z.number().finite().positive(), previousMs: z.number().finite().nonnegative() })).max(100).default([]),
}).superRefine((value, context) => {
  const keys = value.discoveries.map(item => JSON.stringify([item.mapId, item.landmarkId]));
  if (new Set(keys).size !== keys.length) context.addIssue({ code: 'custom', message: 'Duplicate discovery' });
});
export type LifeState = z.infer<typeof lifeStateSchema>;
export const initialLifeState = (): LifeState => ({ version: 1, elapsedMs: 0, discoveries: [], reactions: [], pauses: [], serviceDepartures: [] });
export function advanceLife(state: LifeState, deltaMs: number, visible: boolean): LifeState {
  if (!visible || !Number.isFinite(deltaMs) || deltaMs <= 0 || !Number.isFinite(state.elapsedMs + deltaMs)) return state;
  return { ...state, elapsedMs: state.elapsedMs + deltaMs };
}
export function restoreLife(value: unknown): LifeState {
  const parsed = lifeStateSchema.safeParse(value);
  return parsed.success ? parsed.data : initialLifeState();
}
export function reduceLife(state: LifeState, event: LifeEvent): LifeState {
  if (event.type === 'discovered') {
    if (state.discoveries.some(item => item.mapId === event.mapId && item.landmarkId === event.landmarkId)) return state;
    const { mapId, landmarkId, day } = event;
    return { ...state, discoveries: [...state.discoveries, { mapId, landmarkId, day }] };
  }
  const { mapId, targetId, reaction, atMs } = event;
  if (state.reactions.some(item => item.mapId === mapId && item.targetId === targetId && item.reaction === reaction && item.atMs === atMs)) return state;
  const previous = state.pauses.find(item => item.mapId === mapId && item.targetId === targetId);
  const durationMs = reaction === 'sit' ? 9000 : reaction === 'wave' ? 1800 : 0;
  const pauses = durationMs ? [...state.pauses.filter(item => item.mapId !== mapId || item.targetId !== targetId), {
    mapId, targetId, startMs: atMs, durationMs,
    previousMs: previous ? previous.previousMs + Math.min(previous.durationMs, Math.max(0, atMs - previous.startMs)) : 0,
  }].slice(-100) : state.pauses;
  return { ...state, pauses, reactions: [...state.reactions.filter(item => item.mapId !== mapId || item.targetId !== targetId), { mapId, targetId, reaction, atMs }].slice(-100) };
}
function visible(player: Position, target: Position, reach: number, navigation: Navigation, inspect = false): boolean {
  return Math.hypot(target.x - player.x, target.y - player.y) <= reach && (inspect && navigation.canSee ? navigation.canSee(player, target) : navigation.canWalk(player, target, 0));
}
export function nearbyLife(plan: LifePlan, actors: readonly ActorPose[], player: Position, navigation: Navigation): Affordance[] {
  const options: Affordance[] = [];
  for (const actor of actors) {
    if (!visible(player, actor.position, 1.7, navigation)) continue;
    const kind = actor.greeting ? 'greet' : actor.kind === 'cat' ? 'sit' : 'watch';
    options.push({ id: `${actor.id}/${kind}`, targetId: actor.id, kind, position: actor.position,
      label: lineFor(kind === 'greet' ? 'action-greet' : kind === 'sit' ? 'action-sit' : 'action-look') });
  }
  for (const landmark of plan.landmarks) {
    if (!visible(player, landmark.position, 1.8, navigation, true)) continue;
    options.push({ id: `${landmark.id}/inspect`, targetId: landmark.id, kind: 'inspect', position: landmark.position, label: lineFor('action-look') });
  }
  return options.sort((a, b) => Math.hypot(a.position.x - player.x, a.position.y - player.y) - Math.hypot(b.position.x - player.x, b.position.y - player.y) || a.id.localeCompare(b.id));
}
export function interactLife(state: LifeState, plan: LifePlan, actors: readonly ActorPose[], context: LifeContext, actionId: string, navigation: Navigation): {
  state: LifeState; events: LifeEvent[]; line?: Line;
} {
  const option = nearbyLife(plan, actors, context.player, navigation).find(item => item.id === actionId);
  if (!option || !Number.isFinite(context.elapsedMs) || context.elapsedMs < 0 || !Number.isSafeInteger(context.day) || context.day < 1) return { state, events: [] };
  const events: LifeEvent[] = [];
  if (option.kind === 'inspect') {
    if (!state.discoveries.some(item => item.mapId === plan.mapId && item.landmarkId === option.targetId)) {
      events.push({ type: 'discovered', mapId: plan.mapId, landmarkId: option.targetId, day: context.day });
    }
    const landmark = plan.landmarks.find(item => item.id === option.targetId)!;
    const reaction = ['pond', 'water', 'fountain', 'river', 'pond-deck', 'fishing-jetty', 'rainwater'].includes(landmark.kind) ? 'ripple'
      : ['windchime', 'tree', 'bamboo', 'flowers'].includes(landmark.kind) ? 'sway' : 'watch';
    events.push({ type: 'reacted', mapId: plan.mapId, targetId: option.targetId, reaction, atMs: context.elapsedMs });
  } else {
    const actor = actors.find(actor => actor.id === option.targetId)!;
    events.push({ type: 'reacted', mapId: plan.mapId, targetId: actor.id,
      reaction: option.kind === 'greet' ? 'wave' : option.kind === 'sit' ? 'sit' : actor.kind === 'bird' ? 'flutter' : 'watch', atMs: context.elapsedMs });
    return { state: events.reduce(reduceLife, state), events, line: actor.greeting };
  }
  return { state: events.reduce(reduceLife, state), events };
}

import {safeExitPosition,isExitConnected} from "./exit-safety";
import {restoreLife,advanceLife} from "./life";
import { z } from "zod";
import { facingSchema, pointSchema, type WorldState, type Point, type FeatureId } from "./schema";
import type { MapRegistry } from "./registry";
import { canStand, canWalk, contains, nearbyAnchors } from "./geometry";
const spawn=pointSchema.extend({facing:facingSchema});
const savedSchema=z.object({version:z.literal(1),mapId:z.string(),position:pointSchema,facing:facingSchema,returnPositions:z.record(z.string(),spawn),activeActivity:z.enum(["restaurant","apartment","cats","repairs","garden"]).nullable(),activeAnchorId:z.string().nullable().default(null),life:z.unknown().optional()});
const locationMap:Record<string,string>={restaurant:"restaurant",apartment:"apartment",cats:"courtyard",repairs:"workshop",garden:"rooftop"};
export function createWorld(maps:MapRegistry,location="restaurant"):WorldState {
  const map=maps[locationMap[location]]??maps.restaurant;
  return {version:1,mapId:map.id,position:{x:map.defaultSpawn.x,y:map.defaultSpawn.y},facing:map.defaultSpawn.facing,returnPositions:{},activeActivity:null,activeAnchorId:null,life:restoreLife(null)};
}
export function restoreWorld(value:unknown,maps:MapRegistry,location="restaurant",checkExitConnectivity=true):WorldState {
  const parsed=savedSchema.safeParse(value);
  if(!parsed.success) return createWorld(maps,location);
  const state=parsed.data,map=maps[state.mapId];
  if(!map) return createWorld(maps,location);
  const position=checkExitConnectivity?safeExitPosition(map,state.position):(canStand(map,state.position)?state.position:map.defaultSpawn);
  if(!position)return {...createWorld(maps),life:restoreLife(state.life)};
  const returnPositions=Object.fromEntries(Object.entries(state.returnPositions).filter(([id,p])=>maps[id]&&(checkExitConnectivity?isExitConnected(maps[id],p):canStand(maps[id],p))));
  const activeActivity=state.activeActivity && nearbyAnchors(map,position).some(a=>a.featureId===state.activeActivity)?state.activeActivity:null;
  const activeAnchorId=activeActivity?(nearbyAnchors(map,position).find(a=>a.id===state.activeAnchorId&&a.featureId===activeActivity)?.id??nearbyAnchors(map,position).find(a=>a.featureId===activeActivity)?.id??null):null;
  return {...state,position:{x:position.x,y:position.y},returnPositions,activeActivity,activeAnchorId,life:restoreLife(state.life)};
}
export type WorldAction = {type:"world-clock";elapsedMs:number}|{type:"world-life";actionId:string;elapsedMs:number}|{type:"world-move";position:Point}|{type:"world-interact";anchorId:string}|{type:"world-close"};
export function reduceWorld(state:WorldState,action:WorldAction,maps:MapRegistry):WorldState {
  if(action.type==="world-clock") {const previous=restoreLife(state.life);const life=advanceLife(previous,action.elapsedMs-previous.elapsedMs,true);return life===previous?state:{...state,life};}
  if(action.type==="world-life")return state;
  const map=maps[state.mapId];
  if(!map) return createWorld(maps);
  if(action.type==="world-close") return state.activeActivity?{...state,activeActivity:null,activeAnchorId:null}:state;
  if(action.type==="world-interact") {
    const anchor=nearbyAnchors(map,state.position).find(a=>a.id===action.anchorId);
    if(!anchor||anchor.featureId==="exploration") return state;
    return {...state,activeActivity:anchor.featureId,activeAnchorId:anchor.id};
  }
  if(state.activeActivity || !canWalk(map,state.position,action.position)) return state;
  const dx=action.position.x-state.position.x,dy=action.position.y-state.position.y;
  if(!dx&&!dy) return state;
  const facing=Math.abs(dx)>Math.abs(dy)?dx>0?"east":"west":dy>0?"south":"north";
  const exit=map.exits.find(exit=>contains(exit.rect,action.position));
  if(exit) {
    const target=maps[exit.targetMapId],entrance=target?.entrances.find(e=>e.id===exit.targetEntranceId);
    if(target&&entrance&&canStand(target,entrance.position)) return {...state,mapId:target.id,position:entrance.position,facing:entrance.facing,returnPositions:{...state.returnPositions,[map.id]:{...state.position,facing}},activeActivity:null,activeAnchorId:null};
  }
  return {...state,position:action.position,facing};
}
export function activityLocation(feature:Exclude<FeatureId,"exploration">) {return feature;}

import {courtyardForCats} from "./maps/courtyard";
import {furnitureColliders} from "../features/apartment/world";
import {projectGarden} from "./maps/rooftop";
import type {NeighbourhoodState} from "../neighbourhood/model";
import type {WorldMapDefinition,Point} from "./schema";
import {worldMaps,type MapRegistry} from "./registry";
import {safeExitPosition} from "./exit-safety";
const apartments=new WeakMap<object,WorldMapDefinition>(),roofs=new WeakMap<object,WorldMapDefinition>(),courtyards=new WeakMap<object,{day:number;map:WorldMapDefinition}>();
export function mapsForNeighbourhood(state:NeighbourhoodState,day=state.garden.day??1):MapRegistry {
 let apartment=apartments.get(state.apartment.placements),rooftop=roofs.get(state.garden);
 if(!apartment&&worldMaps.apartment){apartment={...worldMaps.apartment,colliders:[...worldMaps.apartment.colliders,...furnitureColliders(state.apartment)]};apartments.set(state.apartment.placements,apartment);}
